import svg from "../assets/wordmark-stacked.svg?raw";

/**
 * The stacked wordmark, inlined so its parts can animate (see .wordmark rules in index.css):
 * the names rise in, the bead drops onto the cursor i, then the cursor blinks.
 * Generated by Documents/brand/build.mjs; copy stacked-light.svg here after rebuilding.
 */
export function Wordmark({ className = "" }: { className?: string }) {
  return (
    <div
      className={`wordmark ${className}`}
      role="img"
      aria-label="Mustapha Sulaimon. Akanbi, made on purpose."
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  );
}
